 ["history","git rev-parse HEAD\ngit rev-parse upstream/main\ngit merge-base HEAD upstream/main\ngit log --oneline --decorate -10 upstream/main\ngit log --oneline upstream/main..HEAD\ngit diff --check"],
 ["instructions-headings","rg -n '^#{1,4} ' CLAUDE.md CONTRIBUTING.md"]
];
const rs=await Promise.all(cmds.map(async ([name,cmd])=>{
 const r=await tools.exec_command({cmd,workdir:wd,login:false,yield_time_ms:30000,max_output_tokens:30000});
 return `### ${name}\n${r.output}`;
}));
text(rs.join("\n"));

