		}
	}))
	defer srv.Close()

	var out bytes.Buffer
	err := runTrailUpdateWithClientAtPath(t.Context(), &out, api.NewClientWithBaseURL("tok", srv.URL), trailTestBasePath, trailUpdateInputs{
		Branch:      "feature/x",
		Body:        "",
		BodyChanged: true,
	})

	require.NoError(t, err)
	mu.Lock()
	defer mu.Unlock()
	require.Equal(t, map[string]any{"markdown": ""}, put)
