+// boolFieldOrFalse reads a bool field from a decoded JSON map, treating a
+// missing (omitempty-dropped) key the same as an explicit false.
+func boolFieldOrFalse(m map[string]any, key string) bool {
+	v, ok := m[key].(bool)
+	if !ok {
+		return false
+	}
+	return v
+}
